  182	
  183	// Quality, not liveness. Everything above proves the accounts *play*; none of it can tell whether
  184	// they play *well*, which is how a cohort spent a whole session walling one planet and leaving 125
  185	// naked while every counter above read healthy (found 29 Sep 2026). These are the three shapes the
  186	// damage took, stated as thresholds so a human reading the log sees the defect named. They are
  187	// measurement thresholds for this log, not module policy: nothing in the module reads them.
  188	//
  189	//   NAKED_BESIDE_WALLED  an account with a planet at zero defence while a sibling holds a real wall
  190	//   WALL_CEILING         one planet holding more defence units than any single planet needs
  191	//   ALLIANCE_SHARE       one alliance holding more than this share of the AI accounts
  192	//   IDLE_QUEUES          an account that played in the last hour with most buildable planets' queues empty
  193	//   UNIVERSE_SPEED       the economy or a fleet speed above the 1000x grand-test protocol
  194	$nakedBesideWalled = [];
  195	$overCeiling = [];
  196	$WALL_CEILING = 20_000;
  197	$ALLIANCE_SHARE = 0.6;
  198	
  199	$defenceSum = collect(ObjectService::getDefenseObjects())
  200	    ->map(fn ($object): string => '`'.$object->machine_name.'`')
  201	    ->implode(' + ');
  202	
  203	// Moons are left out when the host says which rows are moons: a moon without defence is ordinary,
  204	// and counting it would make this invariant cry wolf until nobody reads it.
  205	$planetQuery = DB::table('planets')->whereIn('user_id', $playerIds);
  206	if (Schema::hasColumn('planets', 'planet_type')) {
  207	    $planetQuery->where('planet_type', '!=', 3);
  208	}
  209	
  210	$byAccount = [];
  211	foreach ($planetQuery->selectRaw("user_id, id, ($defenceSum) as defence")->get() as $row) {
  212	    $byAccount[(int) $row->user_id][] = ['id' => (int) $row->id, 'defence' => (int) $row->defence];
  213	}
  214	
  215	foreach ($byAccount as $accountId => $planets) {
  216	    $walls = array_column($planets, 'defence');
  217	    $strongest = max($walls);
  218	    $naked = count(array_filter($walls, fn (int $units): bool => $units === 0));
  219	
  220	    if ($naked > 0 && $strongest > 1000) {
  221	        $nakedBesideWalled[] = sprintf('player %d: %d planet(s) at zero defence while one holds %s units', $accountId, $naked, number_format($strongest));
  222	    }
  223	
  224	    foreach ($planets as $planet) {
  225	        if ($planet['defence'] <= $WALL_CEILING) {
  226	            continue;
  227	        }
  228	        $overCeiling[] = sprintf('planet %d holds %s defence units', $planet['id'], number_format($planet['defence']));
  229	    }
  230	}
  231	
  232	$allianceShare = [];
  233	if (Schema::hasColumn('users', 'alliance_id')) {
  234	    $members = DB::table('users')->whereIn('id', $playerIds)->whereNotNull('alliance_id')
  235	        ->selectRaw('alliance_id, count(*) as members')->groupBy('alliance_id')->pluck('members', 'alliance_id');
  236	
  237	    foreach ($members as $allianceId => $count) {
  238	        $share = $count / count($playerIds);
  239	        if ($share > $ALLIANCE_SHARE) {
  240	            $allianceShare[] = sprintf('alliance %s holds %d of %d AI accounts (%.0f%%)', $allianceId, $count, count($playerIds), $share * 100);
  241	        }
  242	    }
  243	}
  244	
  245	// A player who logs in fills every planet's build queue where something can be built. IDLE_QUEUES
  246	// counts only the planets the planner has a step for and that have no building in progress: a planet
  247	// whose every candidate the host refuses (no free field, lab busy, price plus reserve) is SATURATED,
  248	// which is information about the universe, not a defect of the account, and is printed below.
  249	$IDLE_SHARE = 0.5;
  250	$idleQueues = [];
  251	$saturated = [];
  252	$playedThisHour = DB::table('ai_work_items')->whereIn('player_id', $playerIds)
  253	    ->where('kind', AiWorkKind::RunSession->value)->where('updated_at', '>=', now()->subHour())
  254	    ->distinct()->pluck('player_id')->map(fn ($id): int => (int) $id)->all();
  255	$busyPlanets = BuildingQueue::query()->where('processed', 0)->where('time_end', '>', time())
  256	    ->distinct()->pluck('planet_id')->map(fn ($id): int => (int) $id)->all();
  257	
  258	// A planet whose build order is already queued is being filled: the session that placed it is done, the
  259	// order runs a few minutes later, and at 1000x the planet reads idle in between.
  260	$ordered = [];
  261	foreach (DB::table('ai_work_items')->whereIn('player_id', $playerIds)->where('kind', AiWorkKind::BuildFirstBuilding->value)
  262	    ->whereIn('state', [AiWorkState::Pending->value, AiWorkState::Retry->value, AiWorkState::Leased->value])->pluck('payload') as $payload) {
  263	    $ordered[] = (int) (json_decode((string) $payload, true)['planet_id'] ?? 0);
  264	}
  265	
  266	$buildingPlanner = app(QueueableBuildingPlanner::class);
  267	
  268	foreach ($playedThisHour as $accountId) {
  269	    $ownPlanets = array_column($byAccount[$accountId] ?? [], 'id');
  270	    if ($ownPlanets === []) {
  271	        continue;
  272	    }
  273	
  274	    $player = app(PlayerServiceFactory::class)->make($accountId, true);
  275	    // "Buildable" means the building planner has a *building* step for the planet. A step that is a
  276	    // technology belongs to the account's one lab, not to this planet's build queue: the account is
  277	    // researching, which is play, and the lab step carries its planet's id, so an account researching
  278	    // read as buildable with an empty build queue on every pass.
  279	    $planned = array_values(array_map(
  280	        static fn ($step): int => $step->planetId,
  281	        array_filter($buildingPlanner->steps($accountId, $player), static fn ($step): bool => $step instanceof QueueableBuilding),
  282	    ));
  283	    // At 1000x a build ends in minutes, so a planet read between its last build ending and the
  284	    // account's next turn is waiting, not neglected. Idle means the account finished a session
  285	    // after the planet's last build ended and the planet still has a legal step and no build.
  286	    $lastSession = (int) strtotime((string) DB::table('ai_work_items')->where('player_id', $accountId)
  287	        ->where('kind', AiWorkKind::RunSession->value)->where('state', AiWorkState::Completed->value)->max('updated_at'));
  288	    // A build ordered around the last session is that session's work: its orders run minutes after it
  289	    // and finish within seconds, so the planet is idle only when a session passed with no order for it.
  290	    $lastBuildEnd = BuildingQueue::query()->whereIn('planet_id', $ownPlanets)->where('canceled', 0)
  291	        ->groupBy('planet_id')->selectRaw('planet_id, max(greatest(time_end, time_start + 300)) as ended')->pluck('ended', 'planet_id');
  292	    $idle = array_filter($ownPlanets, static fn (int $id): bool => in_array($id, $planned, true)
  293	        && !in_array($id, $busyPlanets, true)
  294	        && !in_array($id, $ordered, true)
  295	        && $lastSession > (int) ($lastBuildEnd[$id] ?? 0));
  296	
  297	    if (count($idle) / count($ownPlanets) > $IDLE_SHARE) {
  298	        $idleQueues[] = sprintf('player %d played this hour with %d of %d planets buildable and idle', $accountId, count($idle), count($ownPlanets));
  299	    }
